// swift-tools-version: 5.9
import PackageDescription

// SwiftPM builds the platform-independent streaming, metadata and cache core.
// The iOS app is still generated by XcodeGen and built from its workspace.
let package = Package(
    name: "TeveeStreaming",
    platforms: [.macOS(.v12)],
    products: [.library(name: "TeveeStreaming", targets: ["TeveeStreaming"])],
    targets: [
        .systemLibrary(name: "CSQLite", path: "Support/CSQLite"),
        .target(name: "TeveeStreaming", dependencies: ["CSQLite"], path: "Sources", exclude: [
            "AccessActivationView.swift", "AccessAnnouncement.swift", "CinespiceAccess.swift", "TelegramClient.swift", "TelegramLibraryView.swift", "LibraryStore.swift", "SecureStore.swift", "PlaybackController.swift", "LibraryComponents.swift", "LibrarySettingsView.swift",
            "PlayerOrientation.swift", "VideoExport.swift", "TelegramRangeServer.swift", "TeveeApp.swift", "VLCPlaybackView.swift"
        ], sources: ["NoticeHistory.swift", "AccessReceipt.swift", "HTTPVideoRequest.swift", "TelegramRangeReader.swift", "TelegramMedia.swift", "LibraryDatabase.swift", "ThumbnailCache.swift", "LibraryPaging.swift", "TelegramDiscovery.swift", "TelegramVideoSearch.swift", "PlaybackActivity.swift", "PlayerPresentation.swift", "SubtitleAppearance.swift", "TelegramAuthorizationSetup.swift", "LibraryBrowsing.swift"]),
        .testTarget(name: "TeveeStreamingTests", dependencies: ["TeveeStreaming"], path: "Tests", resources: [.copy("Fixtures")])
    ]
)
